{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary-amine drug closely related to the query scaffold, has an absolute oral bioavailability of 22.0% in normal subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline-like alkaloid, has an absolute oral bioavailability of 30% (range 16–58%) in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Sulpiride, a substituted benzamide with a tertiary amine, has an oral bioavailability of 35% in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a dimethoxyphenyl amide with a basic amine, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Alfentanil, a lipophilic basic drug with substantial first-pass metabolism, has an absolute oral bioavailability of 0.42 ± 0.15 in volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, which shares the dimethoxy-substituted fused-ring motif with the query, has an absolute oral bioavailability of approximately 49% in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, a moderately lipophilic basic drug, has an oral bioavailability of 42–71% in healthy volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "One verapamil study reported a mean bioavailability of 19.4%, just below the 20% threshold, but this is borderline and outweighed by multiple verapamil studies at 22–38%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query molecule is a lipophilic, dimethoxy-substituted basic drug with structural similarity to verapamil, noscapine, encainide, and valbenazine. Transferable experimental evidence consistently shows absolute oral bioavailability at or above 20% for these analogs, with only borderline or condition-specific sub-20% values. Therefore, the query is predicted to have high oral bioavailability at the F ≥20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the exact query molecule.",
    "The query's specific first-pass metabolism, transporter interactions, and solubility profile are not directly characterized.",
    "Most analog evidence comes from different drug classes, so the exact magnitude of F for the query remains uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

